using System.Text;

namespace Colony.Generators;

/// <summary>A small indenting writer; generated files use four-space indentation and LF line endings.</summary>
internal sealed class SourceWriter
{
    private readonly StringBuilder _builder = new();
    private int _indent;

    public SourceWriter Line(string text = "")
    {
        if (text.Length > 0)
        {
            _builder.Append(' ', _indent * 4).Append(text);
        }

        _builder.Append('\n');
        return this;
    }

    /// <summary>Opens a block; <paramref name="continuation"/> (a base/this initializer) goes on its own line before the brace.</summary>
    public SourceWriter Open(string header, string? continuation = null)
    {
        Line(header);
        if (continuation is not null)
        {
            Line("    " + continuation);
        }

        Line("{");
        _indent++;
        return this;
    }

    public SourceWriter Close(string suffix = "")
    {
        _indent--;
        Line("}" + suffix);
        return this;
    }

    /// <summary>Writes the auto-generated header and opens the namespace and every containing partial type.</summary>
    public int OpenPlacement(PlacementModel placement, string origin)
    {
        Line("// <auto-generated/>");
        Line($"// Generated by Colony.Generators from {origin} (spec section 11). Do not edit.");
        Line("#nullable enable");
        Line("#pragma warning disable");
        Line();
        int opened = 0;
        if (placement.Namespace is not null)
        {
            Open($"namespace {placement.Namespace}");
            opened++;
        }

        foreach (var container in placement.Containers)
        {
            Open($"partial {container.Keyword} {container.Name}");
            opened++;
        }

        return opened;
    }

    public void CloseAll(int count)
    {
        for (int i = 0; i < count; i++)
        {
            Close();
        }
    }

    public override string ToString() => _builder.ToString();
}
